// Remember the last catalog version and the CVE IDs already reported.
const sd = $getWorkflowStaticData('global');
const cat = $input.first().json;
const vulns = Array.isArray(cat.vulnerabilities) ? cat.vulnerabilities : [];
const version = cat.catalogVersion;
const FIRST_RUN_DAYS = 7; // first run only: report entries added in the last 7 days
const known = new Set(sd.knownIds || []);
let fresh;
if (sd.catalogVersion === undefined) {
  const cutoff = new Date(Date.now() - FIRST_RUN_DAYS * 86400000).toISOString().slice(0, 10);
  fresh = vulns.filter(v => v.dateAdded >= cutoff);
} else if (sd.catalogVersion === version) {
  fresh = [];
} else {
  fresh = vulns.filter(v => !known.has(v.cveID));
}
const chunks = [];
for (let i = 0; i < fresh.length; i += 50) chunks.push(fresh.slice(i, i + 50).map(v => v.cveID).join(','));
return [{ json: {
  hasNew: fresh.length > 0,
  catalogVersion: version,
  previousVersion: sd.catalogVersion || null,
  catalogCount: vulns.length,
  newCount: fresh.length,
  newEntries: fresh,
  allIds: vulns.map(v => v.cveID),
  epssChunks: chunks,
} }];

const prev = $('Find new entries').first().json;
const scores = {};
let scoreDate = null;
for (const item of $input.all()) {
  for (const d of (item.json.data || [])) { scores[d.cve] = d; scoreDate = d.date; }
}
const rows = prev.newEntries.map(v => {
  const s = scores[v.cveID];
  return {
    cve: v.cveID, vendor: v.vendorProject, product: v.product, name: v.vulnerabilityName,
    date_added: v.dateAdded, due_date: v.dueDate, ransomware: v.knownRansomwareCampaignUse,
    epss: s ? parseFloat(s.epss) : null, percentile: s ? parseFloat(s.percentile) : null,
    nvd: 'https://nvd.nist.gov/vuln/detail/' + v.cveID,
  };
});
rows.sort((a, b) => (b.epss === null ? -1 : b.epss) - (a.epss === null ? -1 : a.epss));
const pct = x => x === null ? 'not scored yet' : (x * 100).toFixed(2) + '%';
const lines = rows.map((r, i) => (i + 1) + '. ' + r.cve + '  EPSS ' + pct(r.epss) + (r.percentile === null ? '' : ' (percentile ' + (r.percentile * 100).toFixed(1) + ')') + '\n   ' + r.vendor + ' ' + r.product + ': ' + r.name + '\n   Added ' + r.date_added + ', CISA due date ' + r.due_date + ', known ransomware use: ' + r.ransomware + '\n   ' + r.nvd);
const text = 'CISA KEV additions since the last run: ' + rows.length + ' (catalog ' + prev.catalogVersion + ', was ' + (prev.previousVersion || 'none') + ')\nRanked by FIRST EPSS score' + (scoreDate ? ' of ' + scoreDate : '') + ', highest first. EPSS is the estimated probability of exploitation in the next 30 days.\n\n' + lines.join('\n\n') + '\n\nSources: https://www.cisa.gov/known-exploited-vulnerabilities-catalog and https://www.first.org/epss/';
// Save state only after every step before this node worked.
const sd = $getWorkflowStaticData('global');
sd.catalogVersion = prev.catalogVersion;
sd.knownIds = prev.allIds;
sd.lastRun = new Date().toISOString();
return [{ json: { count: rows.length, catalogVersion: prev.catalogVersion, epssDate: scoreDate, subject: 'CISA KEV: ' + rows.length + ' new, top EPSS ' + pct(rows[0] ? rows[0].epss : null), text, rows } }];

const sd = $getWorkflowStaticData('global');
const prev = $json;
sd.catalogVersion = prev.catalogVersion;
sd.knownIds = prev.allIds;
sd.lastRun = new Date().toISOString();
return [{ json: { message: 'No new KEV entries. Catalog version ' + prev.catalogVersion, catalogVersion: prev.catalogVersion } }];
